# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">THEME 3: PERSONAL LIFE — BODY PARTS &amp; PHYSICAL FEATURES</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Basic Body Parts (Vücudun Bölümleri)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Head (Baş) · Face (Yüz) · Neck (Boyun)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Eye (Göz) · Nose (Burun) · Hair (Saç)</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Tooth / Teeth (Diş / Dişler) · Arm (Kol)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hand (El) · Finger (Parmak) · Leg (Bacak)</text>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Foot / Feet (Ayak / Ayaklar) · Body (Vücut)</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Düzensiz Çoğullar: tooth → teeth · foot → feet</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Physical Features (Fiziksel Özellikler)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• Height (Boy): tall (uzun), short (kısa), average (orta)</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11.5" fill="#831843">• Build (Yapı): thin / slim (zayıf, ince), average</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11.5" fill="#831843">• Hair (Saç): straight (düz), wavy (dalgalı), curly (kıvırcık)</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11.5" fill="#831843">• Face (Yüz): round (yuvarlak), oval, square (kare)</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">She is tall and slim. She has got curly hair.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">CLOTHES, ACCESSORIES &amp; POSSESSIVE ADJECTIVES</text>\n  <rect x="20" y="46" width="330" height="194" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="185" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Clothes &amp; Accessories (Giysiler ve Aksesuarlar)</text>\n  <text x="185" y="96" text-anchor="middle" font-size="11.5" fill="#14532d">• Coat (Mont) · Raincoat (Yağmurluk) · Jacket (Ceket)</text>\n  <text x="185" y="120" text-anchor="middle" font-size="11.5" fill="#14532d">• Jumper / Sweater (Kazak) · Shirt (Gömlek) · T-shirt</text>\n  <text x="185" y="144" text-anchor="middle" font-size="11.5" fill="#14532d">• Trousers / Jeans (Pantolon/Kot) · Skirt (Etek) · Dress</text>\n  <text x="185" y="168" text-anchor="middle" font-size="11.5" fill="#14532d">• Boots (Bot) · Shoes (Ayakkabı) · Socks (Çorap)</text>\n  <text x="185" y="192" text-anchor="middle" font-size="11.5" fill="#14532d">• Scarf · Headscarf · Gloves · Belt · Hat · Glasses · Watch</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Sıfatlar: thick, thin, trendy, comfortable, ordinary, cool</text>\n\n  <rect x="365" y="46" width="315" height="194" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="522" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Possessive Adjectives &amp; Have/Has Got</text>\n  <text x="522" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">• I → my (benim) · You → your (senin/sizin)</text>\n  <text x="522" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">• He → his (onun-erkek) · She → her (onun-kız)</text>\n  <text x="522" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">• We → our (bizim) · They → their (onların)</text>\n  <text x="522" y="174" text-anchor="middle" font-size="11.5" fill="#92400e">• I/You/We/They have got blue eyes.</text>\n  <text x="522" y="196" text-anchor="middle" font-size="11.5" fill="#92400e">• He/She has got wavy brown hair.</text>\n  <text x="522" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Fiiller: to wear (giymek), to try on (denemek), to own</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DAILY ROUTINES, FREQUENCY ADVERBS &amp; QUESTION TAGS</text>\n  <rect x="20" y="46" width="320" height="194" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Adverbs of Frequency (How often...?)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 100% — always (daima / her vakit)</text>\n  <text x="180" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 80% — usually (genellikle)</text>\n  <text x="180" y="150" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 50% — sometimes (bazen / ara sıra)</text>\n  <text x="180" y="176" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">• 15% — rarely (nadiren) · 0% — never (hiç)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="11" fill="#475569">He usually wears sunglasses in summer.</text>\n\n  <rect x="360" y="46" width="320" height="194" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Simple Present &amp; Question Tags</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">• She wears her blue coat every winter.</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#164e63">• Olumlu cümle → Olumsuz kuyruk sorusu:</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" fill="#155e75">She reads a magazine every evening, doesn\'t she?</text>\n  <text x="520" y="172" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#164e63">• Olumsuz cümle → Olumlu kuyruk sorusu:</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" fill="#155e75">You don\'t play video games at night, do you?</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Social: Don\'t make fun of people! · Let\'s sort out the problem!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
